CREATE TABLE `net_work_metrics` (
  `id` varchar(19) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  `node` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '''节点名称''',
  `category` varchar(124) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '''指标类型''',
  `metrics` varchar(124) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '''指标名''',
  `unit` varchar(6) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '''单位''',
  `current_value_source_id` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '''调用观测平台当天峰值Id''',
  `current_value` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '''当前值''',
  `historical_peak_source_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '''历史峰值数据源Id''',
  `historical_peak` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '''历史峰值''',
  `wow_change` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '‘周同比’',
  `dod_change` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '''日环比''',
  `history_peak_source_id` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '''调用观测平台历史峰值Id''',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_net_work_metrics_deleted_at` (`deleted_at`) USING BTREE
