DROP TABLE IF EXISTS `panels`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `panels` (
  `id` varchar(19) NOT NULL,
  `dashboard_id` varchar(19) NOT NULL,
  `title` varchar(256) NOT NULL,
  `type` varchar(16) NOT NULL COMMENT 'panel type: bar, line, pie, gauge, table',
  `grid_pos_x` int NOT NULL DEFAULT '0',
  `grid_pos_y` int NOT NULL DEFAULT '0',
  `grid_pos_w` int NOT NULL DEFAULT '12',
  `grid_pos_h` int NOT NULL DEFAULT '7',
  `datasource` json DEFAULT NULL,
  `options` json DEFAULT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `deleted_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_dashboard_id` (`dashboard_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
